node -e "
import('node:fs').then(fs => {
  fs.writeFileSync('comprehensive.test.tsx', \`
import { it, expect, vi } from 'vitest';
import React from 'react';
import * as db from '@/lib/db';

vi.mock('next/cache', () => ({
  revalidateTag: vi.fn(),
  unstable_cache: vi.fn((fn, keys, opts) => fn),
}));

it('verifies catalog caching, rendering, and background invalidation', async () => {
  const cache = await import('next/cache');
  const { default: Page } = await import('@/app/page');

  // Verify unstable_cache was called with products tag
  expect(cache.unstable_cache).toHaveBeenCalledWith(
    db.getAllProducts,
    ['products'],
    { tags: ['products'] }
  );

  // Render Page
  const jsx = await Page();
  expect(jsx).toBeDefined();

  // Find the form
  const form = jsx.props.children.find((c: any) => c?.type === 'form');
  expect(form).toBeDefined();

  // Find the submit button
  const button = form.props.children;
  expect(button.props.children).toBe('Sync latest catalog');

  // Execute inline server action
  await form.props.action();

  // Verify revalidateTag was called with tag 'products' and profile 'max'
  expect(cache.revalidateTag).toHaveBeenCalledWith('products', 'max');
});
\`);
});
" && npx vitest run comprehensive.test.tsx && rm comprehensive.test.tsx
